from concurrent.futures import ThreadPoolExecutor, ProcessPoolExecutor
import app

def sequential(f, jobs):
    for j in jobs: f(j)
def threads(f, jobs):
    with ThreadPoolExecutor(4) as p: list(p.map(f, jobs))
def processes(f, jobs):
    with ProcessPoolExecutor(4) as p: list(p.map(f, jobs))

for how in (sequential, threads, processes):
    app.run(how)

